css='''*{box-sizing:border-box}body{margin:0;background:#f5f3ed;color:#172b35;font:17px/1.65 system-ui,sans-serif}main{max-width:1050px;margin:auto;padding:55px 28px}nav{display:flex;gap:24px;flex-wrap:wrap;border-bottom:1px solid #cbd1cd;padding-bottom:18px;font-size:14px}a{color:#176357}h1{font:600 clamp(32px,5vw,58px)/1.12 Georgia,serif;max-width:850px;margin:38px 0 24px}h2{font:600 27px/1.25 Georgia,serif;margin-top:38px}h3{font-size:18px;margin-bottom:8px}.kicker{letter-spacing:.12em;text-transform:uppercase;font-size:12px;color:#49685f}.lead{font-size:21px;max-width:850px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:28px 0}.stats div{border-top:2px solid #277464;padding:12px 0}.stats strong{font-size:28px;display:block}.stats span{font-size:13px}.card{background:#fff;padding:24px;margin:18px 0;border:1px solid #dce0db;border-radius:5px}.small,small{font-size:14px;color:#4e6167}.tag{font:12px system-ui;text-transform:uppercase;letter-spacing:.04em;color:#176357}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:14px 12px;border-bottom:1px solid #cbd1cd;text-align:left;vertical-align:top}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf0e9;padding:18px;font-size:14px}footer{border-top:1px solid #cbd1cd;margin-top:40px;padding-top:20px;font-size:13px}details{margin:18px 0}summary{cursor:pointer;font-weight:600}.scroll{overflow-x:auto}@media(max-width:650px){.stats{grid-template-columns:repeat(2,1fr)}main{padding:28px 18px}table{min-width:650px}}'''
nav='<nav aria-label="Main navigation"><a href="index.html">Two-minute brief</a><a href="evidence.html">Evidence &amp; taxonomy</a><a href="pitches.html">Lab pitches</a><a href="submission-code.zip" download>Report + code ZIP</a></nav>'
def page(name,title,body):
 (DIST/name).write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'+title+'</title><link rel="stylesheet" href="style.css"></head><body><main>'+nav+body+'<footer>Field Engineer take-home · V4 · November 5, 2026<br>Public edition: sanitized report and selected code. Raw sources, native submissions and personal review records remain in the separate local evidence archive.</footer></main></body></html>')
(DIST/'style.css').write_text(css)
page('index.html','Professional work: correctness beyond the saved answer','''<p class="kicker">An exploratory GDPval study</p><h1>Correctness must survive<br>the next action.</h1><p class="lead">Can agents produce professional deliverables that remain correct when calculated, edited and used—and can our evaluation distinguish a consequential error from an unnecessary requirement?</p><div class="stats"><div><strong>40</strong><span>original tasks, eight occupations</span></div><div><strong>40</strong><span>tasks with saved submissions</span></div><div><strong>33</strong><span>structurally valid assessments</span></div><div><strong>4</strong><span>scoped, assisted human reviews</span></div></div><p>We retained all five public tasks in each selected occupation: purchasing, project management, shipping/inventory, accounting, administrative services, finance, order clerks and operations. File-rich tasks expose calculations, dependencies and usable instructions. Selection was purposive; three execution cohorts remain separate.</p><div class="card"><h3>01 · A saved answer can be numerically wrong.</h3><p>A tax draft understated regular tax by <strong>$2,046</strong> under its own assumptions. Recalculation and an assisted user review supported correction; other tax inputs remain unresolved.</p><h3>02 · A correct-looking workbook can fail when edited.</h3><p>A payroll workbook awarded a conditional premium in a tested ineligible state. The reviewer required revision for reusable payroll. No original-sample overpayment or actual payment was established.</p><h3>03 · A rubric can demand more than the task.</h3><p>An order audit was correct on its supplied export. Zero/blank case-pack failures appeared only after input changes. The reviewer accepted it on the supplied evidence and classified hardening as optional.</p></div><p><strong>Dataset ask:</strong> commission a 30-family private pilot of numerical rules, conditional workflows and task-scope boundaries: native files, executable checks, expert rationales and correction pairs. Reserve 10 families for evaluation; keep 20 for development. Test prompt/tool repairs before training.</p><p class="small"><strong>Limits and cost:</strong> four selected reviews by a non-specialist, with evidence and prior findings shown; no representative acceptance rate, validated grader accuracy, model ranking or training gain. Recorded API charges: $12.69; unresolved-charge reserve: $16.62. In-app cost is unknown. <a href="evidence.html">Inspect evidence, methods and caveats →</a></p>''')
page('evidence.html','Evidence and failure taxonomy','''<p class="kicker">Methods &amp; interpretation</p><h1>Keep the failure types separate.</h1><p>These categories classify findings, not mutually exclusive task-level failure rates. The four selected reviews cover four tasks and four scoped decisions; the source/tool examples below are unreviewed uncertainties. Counts must not be added into a population failure rate.</p><div class="scroll"><table><thead><tr><th>Category / evidence</th><th>Consequence and correction</th><th>Data opportunity / next test</th></tr></thead><tbody><tr><td><strong>Saved calculation error</strong><br>Tax return, TAX-05. One scoped human review required revision. The saved bracket base was 32,291; the reproduced base was 34,337.</td><td>Regular tax 60,407 → 62,453, holding the other draft assumptions fixed. Update dependent totals. Material numerical error; no actual filing or loss claimed.</td><td>Source-table-to-form calculations with formula traces and corrective examples. Test exact outputs on unseen years/rules, with applicable sources supplied.</td></tr><tr><td><strong>Conditional behavior failure</strong><br>Musician payroll, PAY-04, earlier V3 cohort. One review required revision after an editable-state probe.</td><td>Premium requires quartet membership AND the quartet constituting the entire acoustic string section. Preserve the conflict warning when eligibility inputs conflict; approval cannot erase eligibility. No saved-sample overpayment established.</td><td>Valid/invalid boundary states, executable predicates and expert explanations. Test both erroneous payments and wrongly withheld eligible payments.</td></tr><tr><td><strong>Presentation defect</strong><br>Planogram, POG-05. One review required revision.</td><td>A final instructions line clips in LibreOffice print export; main planogram is readable. Adjust layout and retest. Excel reproduction remains untested. Local usability issue, not a demonstrated calculation error.</td><td>First test render/print tooling and repair prompts. Collect cross-viewer layout examples only if persistent errors justify them.</td></tr><tr><td><strong>Source/tool uncertainty</strong><br>Examples: month-end conflicting schedules; sales-pivot native-use check.</td><td>No demonstrated wrong business amount from these gaps. Resolve source authority and perform native refresh/edit checks. Keep unresolved verdicts uncertain.</td><td>Clarification and source-authority tasks; tool qualification before model attribution. Measure justified abstention and unnecessary holds separately.</td></tr></tbody></table></div><div class="card"><h2>Counterexample: do not train the grader to reject valid work.</h2><p>PRICE-03 was flagged because an order workbook divided by zero under zero/blank case-pack probes. The original export had positive case packs and correct results. The user treated handling those added states as optional and accepted the workbook on the evidence shown. Preserve the raw judge flag alongside this scope decision. One selected disagreement does not establish a judge false-positive rate.</p></div><h2>Execution and grading</h2><div class="scroll"><table><tr><th>Cohort</th><th>Tasks / submissions</th><th>Contract-valid assessments</th><th>Diagnostic human reviews</th></tr><tr><td>V2 API, including separately recorded recoveries</td><td>15 / 15</td><td>8 / 15</td><td>0</td></tr><tr><td>V3 in-app extension</td><td>5 / 5</td><td>5 / 5</td><td>1</td></tr><tr><td>V4 native builders + research</td><td>20 / 20</td><td>20 / 20</td><td>3</td></tr></table></div><p>The new twenty tasks requested GPT-6.1 Sol solvers and separate GPT-6 Astra judges. Solvers received original prompts and reference files, native builders, inspection tools and task-required research. Shared-filesystem isolation was instruction-based. Sources, submitted files, revisions and available traces were hashed. One task needed a fresh-context recovery following transport interruption.</p><p>Frozen project rubrics—not official GDPval scores—checked requirements, operative conditions, source/output evidence, calculations and native behavior. The new cohort yielded 12 provisional passes, five uncertain and three flagged tasks. Schema/quote validity is not semantic accuracy. Both solver and judge are from the OpenAI family; served builds, seeds, temperature, app tokens and cost are unavailable. Seven earlier invalid assessments are excluded from valid-result claims.</p><h2>Human evidence and cost</h2><p>Four purposively selected, evidence-assisted, nonblind reviews: tax, payroll, order audit and planogram. The reviewer reported no specialist background in these domains. Three decisions required revision; one accepted the work on the supplied evidence. These are scoped decisions, not independent full-output expert audits. Self-reported active review time: 5 + 7 + 8 + 8 = 28 minutes; labor price is unknown.</p><p>Ledger scope: the preserved V2–V4 campaign, not every historical project experiment. Confirmed API charges $12.6855182; unresolved-charge reserves $16.61936074; committed $29.30487894 under its recorded $30 ceiling. Reserves are not confirmed charges or account balance. V4 added no OpenRouter calls; in-app usage is not free merely because its dollar cost is unavailable. Cost per accepted deliverable is not estimable.</p><h2>What the slice leaves out</h2><p>The roster covers all five public tasks within each of eight selected occupations, not the economy or full occupational task distributions. Earlier results informed occupation selection; the additional twenty IDs were fixed before their outputs. V4 prompts were unchanged, while execution capabilities and earlier-cohort input policies differed. Public pretraining exposure is unknown; no contamination-free claim is made. Related accounting tasks may share business context. No model ranking, causal variant effect or training gain is established.</p><h2>Audit access</h2><p><a href="evidence-snapshot.json">Sanitized numbers and evidence map</a> · <a href="submission-code.zip">Download report, selected implementation and offline count check</a>. The code bundle explains which dependencies and raw inputs are excluded. Its count check reproduces published summaries, not model inference or raw evidence adjudication.</p>''')
page('pitches.html','OpenAI and Anthropic dataset pitches','''<p class="kicker">Two research conversations</p><h1>Buy the missing evidence,<br>then test the intervention.</h1><div class="card"><h2>Anthropic: preserve the condition where action happens.</h2><p>Our clearest behavioral case is a reusable payroll workbook that applied a premium in a tested ineligible state. A separate order-audit case shows the opposite risk: rejecting valid work for behavior the original task never required. A useful evaluator must catch consequential violations without rewarding unnecessary refusal.</p><p><strong>Ask:</strong> partner on 30 freshly authored, permissioned workflow families: 10 numerical-rule tasks, 10 approval/eligibility workflows and 10 task-scope/clarification boundaries. Each includes approved sources, plausible drafts, native artifacts, authorized-action and violation controls, and expert explanations of the operative constraint.</p><p><strong>First experiment:</strong> freeze 10 evaluation families before model access; use the other 20 for prompt/tool development. On held-out families measure missed consequential errors, false acceptance, unnecessary holds, expert acceptance and review minutes. Independently validate edits and compare harmless rewording with broken-condition versions. Report missing judgments and abstentions. One expert labels every family; a second adjudicates failures/disagreements and a prespecified sample of passes.</p><p><strong>Claim today:</strong> scoped diagnostic evidence motivates the dataset. We have not validated judge accuracy, demonstrated deception, or measured a training improvement. V5 is a prepared development check with human validation pending, not a completed result.</p></div><div class="card"><h2>OpenAI: make professional-work feedback executable.</h2><p>The tax draft’s $2,046 calculation error and the payroll boundary-state failure point to different feedback signals: correct source-table arithmetic, and correct behavior after a supported input change. The order-audit review shows why reward rules must also respect the task contract.</p><p><strong>Ask:</strong> commission the same 30-family private pilot in a GDPval-style format: task requests, native sources, gold deliverables, executable numerical and conditional checks, expert correction rationales and preference pairs. For each family, provide one expert-approved deliverable and two contrasting candidates with independently checked differences. Include native open/edit/print checks where the task requires them.</p><p><strong>First experiment:</strong> reserve 10 families for evaluation; use 20 for development and prompt/tool repair. Only if verified failures persist, use separate development families for SFT/RL. Hold out complete business families, templates and source lineages; keep evaluator keys inaccessible to solvers. Use hidden boundary tests, authorized-action controls and expert audits to detect reward gaming.</p><p><strong>Decision:</strong> select the lowest total cost per expert-accepted deliverable among systems meeting a customer-defined consequential-error threshold. Count inference, grading, review and correction. The small pilot characterizes errors and costs; it cannot certify a rare-error ceiling. Expand independent held-out sampling before making that deployment claim.</p></div><h2>Concrete delivery specification</h2><ul><li>30 fresh, rights-cleared families, with 10 held out and 20 development-only. Existing public GDPval tasks are discovery evidence, not the private product.</li><li>Three candidate deliverables per family: one expert-approved reference and two controlled alternatives; at least two adjudicated preference pairs and rationales per family.</li><li>Source permissions, task-family IDs, expert review status, artifact hashes, executable checks and explicit source-uncertainty records.</li><li>A versioned release with family-level leakage checks; proposed quarterly refresh or earlier refresh when source policy changes.</li><li>Pilot pricing to follow a timed five-family production sample. No invented collection cost or promised training gain.</li></ul><h2>Hard questions, defensible answers</h2><details><summary>Is your grader validated?</summary><p>No. Structural validation checks evidence format and traceability. Four assisted reviews are diagnostic, not independent accuracy calibration. We need fresh human labels and controlled sensitivity tests.</p></details><details><summary>Why is this a data problem rather than a tool problem?</summary><p>Some findings are tool or source problems. Native checks and prompt/tool repairs come first. Corrective data is a hypothesis for persistent source-grounded reasoning and conditional failures; improvement must be tested on unseen families.</p></details><details><summary>Can you rank models from forty tasks?</summary><p>No. Forty is the unique-task inventory across different execution cohorts. Models, tools and budgets are not matched. The evidence supports failure analysis.</p></details><details><summary>Did the user confirm every finding?</summary><p>No. Four tasks received scoped non-specialist, evidence-assisted review. Unreviewed criteria remain model assessments or uncertainties. The review record distinguishes saved errors, changed-input probes and viewer-specific defects.</p></details><details><summary>How do you avoid contamination?</summary><p>Public-task pretraining exposure is unknown. The proposed private dataset uses fresh permissioned sources and family-separated development/evaluation. Near-duplicate and template checks reduce leakage; they do not prove no prior exposure.</p></details>''')
snapshot={'schema':'v4-sanitized-delivery-1','source_report_sha256':hashlib.sha256((ROOT/'output/evaluation_v4/report.json').read_bytes()).hexdigest(),'counts':report['counts'],'cohorts':report['cohorts'],'v4_provisional_outcomes':{'pass':12,'uncertain':5,'flagged':3},'review_scope':'Four selected, assisted, non-specialist diagnostic reviews; no population acceptance rate','review_minutes':[5,7,8,8],'cost':report['cost'],'evidence':[{'id':'tax','category':'saved_calculation','task_id':'43dc9778-450b-4b46-b77e-b6d82b202035','criterion':'TAX-05','regular_tax_saved':60407,'regular_tax_corrected':62453,'difference':2046,'human':'revision required, scoped assisted review'}, {'id':'payroll','category':'conditional_behavior','task_id':'4520f882-715a-482d-8e87-1cb3cbdfe975','criterion':'PAY-04','cohort':'V3','human':'revision required for reusable payroll; controlled changed-input state'}, {'id':'order','category':'scope_counterexample','task_id':'1137e2bb-bdf9-4876-b572-f29b7de5e595','criterion':'PRICE-03','human':'accepted on evidence supplied; added zero/blank-input robustness optional'}, {'id':'planogram','category':'presentation','task_id':'0fad6023-767b-42c1-a1b3-027cd4f583cb','criterion':'POG-05','human':'revision required based on LibreOffice clipping; Excel untested'}]}
(DIST/'evidence-snapshot.json').write_text(json.dumps(snapshot,indent=2)+'\n')
